INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(101060, 'ruRU', '', 'Возвращайтесь в глубины! Ай! Моя спина!', 24330),
(101061, 'ruRU', '', 'Твоя магия здесь слаба!', 24330),
(101062, 'ruRU', '', 'Они пытаются сорвать наше заклинание! Остановите их!', 24330),
(101063, 'ruRU', '', 'Получается, нам просто нужно больше времени!', 24330),
(101064, 'ruRU', '', 'Мы пробовали мир, теперь попробуем войну!', 24330),
(101065, 'ruRU', '', 'Я уже слишком стар для этого.', 24330),
(101066, 'ruRU', '', 'За Ривермейн! ... Ты что-то сказал? Говори громче!', 24330),
(101083, 'ruRU', '', 'Сюда, сёстры!', 24330),
(101084, 'ruRU', '', 'Добро пожаловать в "Спасибо за всё". У нас найдётся лучшее для всех твоих нужд в кузнечном деле и горной добыче.', 24330),
(101088, 'ruRU', '', 'У меня правда есть лишние, но я не особо хочу с ними расставаться. Разве что...', 24330),
(101089, 'ruRU', '', 'Не согласишься ли выполнить для меня небольшое поручение? Сделаешь — и я обещаю дать тебе несколько стоек для доспехов.', 24330),
(101090, 'ruRU', '', 'Мне просто нужно, чтобы ты отнёс моё платье Шенди в чистку. Оно всё в саже.', 24330),
(101091, 'ruRU', '', 'Этот Шенди... он точно знает, как вывести кровь и прочую мерзость! Вот стойки для доспехов, что я тебе обещала.', 24330),
(101098, 'ruRU', '', 'Делаем ставки на то, сколько продержится гном?', 24330),
(101111, 'ruRU', '', 'Сними сапоги и немного отдохни. Нет ничего лучше сна под звёздами.', 24330),
(101117, 'ruRU', '', 'Пока арканум позволит мне выполнить большую часть работы, для финального слова мне всё же понадобится более сильный реагент. Если точнее — осколок лей-света.$b$bТеперь давай пустим в ход эти большие, страшные демонические слова!', 24330),
(101118, 'ruRU', '', 'Встретимся у Речного Излома, как сможешь, $n. Я буду там ждать — мои старые кости уже не те, что раньше.', 24330),
(101122, 'ruRU', '', 'Не стоит волноваться. Я не подведу, Латосиус.', 24330),
(101127, 'ruRU', '', 'Ты ступаешь в землю мёртвых, смертный. Король-лич повелел, что живым нет входа в Ледяную Корону!', 24330),
(101130, 'ruRU', '', 'Солдаты! Захватчики идут на нас. Не дайте им пройти! За Калимдор!', 24330),
(101132, 'ruRU', '', 'Мы похороним вас здесь, глупцы.', 24330),
(101144, 'ruRU', '', 'Ты являешь честь своими деяниями.', 24330),
(101145, 'ruRU', '', 'Будь бдителен и береги себя от скверны.', 24330),
(101146, 'ruRU', '', 'Пусть ты всегда стремишься к равновесию.', 24330),
(101147, 'ruRU', '', 'Моё благословение тебе.', 24330),
(101154, 'ruRU', '', 'Пробудись, Кровавое Крыло! Разорви моего врага на части!', 24330),
(101155, 'ruRU', '', 'Твоё почтение принято со смирением, $r. Мудрость, которую я дарую чтущим меня — бережливость.', 24330),
(101156, 'ruRU', '', 'Не выбрасывай утиль только потому, что не видишь ему немедленного применения.', 24330),
(101157, 'ruRU', '', '$n, спасибо, что пришёл. В этом зале ты можешь увидеть историю моего народа. Историю, частью которой я была большую часть века.', 24330),
(101158, 'ruRU', '', 'У нас богатая история и жатвы, и войны. Мы никогда не бываем сильнее, чем вместе с другими племенами.', 24330),
(101159, 'ruRU', '', 'Ах, Громовой Тотем. Вот это правильно ощущается. А вот мои колени? Не очень.', 24330),
(101160, 'ruRU', '', 'Да будет известно, что я, Джейл Ривермейн, вождь племени Ривермейн, вновь заявляю о своей верности Высокогорью.', 24330),
(101161, 'ruRU', '', 'Вместе мы — Высокогорье!', 24330),
(101163, 'ruRU', '', 'Множество малых вещей всегда складываются во что-то большее, и зачастую не менее крепкое.', 24330),
(101164, 'ruRU', '', 'Теперь, когда угроза дрогбаров моему народу подавлена, мы рады вновь присоединиться к делу Майлы Высокогорье. Я готова начать ритуал, когда скажешь.', 24330),
(101179, 'ruRU', '', 'Не только у тебя есть прислужники, демон!', 24330),
(101180, 'ruRU', '', 'Задай этим демонам жару по заслугам!', 24330),
(101181, 'ruRU', '', 'Мило, что ты объявился. Подкрепления пока особо не видно.', 24330),
(101182, 'ruRU', '', 'Ну и вечеринка, а? Столько незваных гостей.', 24330),
(101183, 'ruRU', '', 'Будет приятно, когда здесь всё вернётся в норму.', 24330);
